// ====================================================
// NODO: Log de Evaluación (para Monitoreo)
// ====================================================
// Guarda cada evaluación para poder graficar tendencias.
// En producción esto iría a una DB. Acá lo guardamos en el output.

const registro = {
  timestamp: new Date().toISOString(),
  consulta: $json.consulta,
  respuesta_ia: $json.respuesta_residente,
  similitud_coseno: $json.similitud_coseno,
  similitud_porcentaje: $json.similitud_porcentaje,
  veredicto_jefe: $json.veredicto_jefe,
  aprobado_embedding: $json.aprobado_embedding,
  resultado_final: $json.aprobado_embedding && ($json.veredicto_jefe || '').includes('APROBADO') ? 'APROBADO' : 'RECHAZADO'
};

return [{ json: registro }];
